    }, 30000)
    const wfAfter = await getWorkflow(app.shell, wfId)
    const pubTaskId = wfAfter?.taskIds?.publish ?? null
    const pubTask = pubTaskId
      ? await evalIn(app.shell, `window.browserAPI.ai.ptaskGet(${J(pubTaskId)})`, true)
      : null

