    for (let i = 0; i < 3; i++) {
      if (!pubTaskId) break
      resumeAttempts.push(await evalIn(app.shell, `window.browserAPI.ai.ptaskStart(${J(pubTaskId)})`, true).catch((e) => ({ error: String(e) })))
      await sleep(400)
    }
    const approveAgain = []
    for (let i = 0; i < 2; i++) {
